// G-Counter CRDT — grow-only distributed counter
class GCounter {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.slots = { [nodeId]: 0 };
  }

  increment(amount = 1) {
    this.slots[this.nodeId] = (this.slots[this.nodeId] || 0) + amount;
  }

  value() {
    return Object.values(this.slots).reduce((sum, v) => sum + v, 0);
  }

  // Merge: component-wise maximum
  merge(otherSlots) {
    for (const [node, count] of Object.entries(otherSlots)) {
      this.slots[node] = Math.max(this.slots[node] || 0, count);
    }
  }
}

// OR-Set CRDT — add/remove set with conflict-free re-add
const { randomUUID } = require('crypto');

class ORSet {
  constructor() {
    this.entries = new Map(); // element -> Set of tags
    this.tombstones = new Set(); // removed tags
  }

  add(element) {
    const tag = randomUUID();
    if (!this.entries.has(element)) this.entries.set(element, new Set());
    this.entries.get(element).add(tag);
    return tag; // broadcast (element, tag) to peers
  }

  remove(element) {
    const tags = this.entries.get(element) || new Set();
    tags.forEach(tag => this.tombstones.add(tag)); // tombstone all current tags
    // Future adds create new tags not in tombstones
  }

  has(element) {
    const tags = this.entries.get(element) || new Set();
    return [...tags].some(tag => !this.tombstones.has(tag));
  }

  // Merge two OR-Sets: union entries, union tombstones
  merge(other) {
    for (const [element, tags] of other.entries) {
      if (!this.entries.has(element)) this.entries.set(element, new Set());
      tags.forEach(tag => this.entries.get(element).add(tag));
    }
    other.tombstones.forEach(tag => this.tombstones.add(tag));
  }
}

// Demo: concurrent add/remove, then merge
const replicaA = new ORSet();
const replicaB = new ORSet();

const tag1 = replicaA.add('apple'); // A adds apple
replicaB.merge({ entries: new Map([['apple', new Set([tag1])]]), tombstones: new Set() });
replicaB.remove('apple');           // B concurrently removes apple
replicaA.add('apple');              // A re-adds apple (new tag)

// After merging: apple exists (new tag survives tombstone)
console.log(replicaA.has('apple')); // true
console.log(replicaB.has('apple')); // false (hasn't merged A's re-add yet)

// CRDT catalog and properties

// G-Counter: increment-only counter
//   Merge: component-wise max, value = sum(slots)
//   Use: view counts, download counters, rate limiting

// PN-Counter: increment and decrement counter
//   Structure: G-Counter(P) - G-Counter(N)
//   Use: inventory counts, follower counts

// G-Set: add-only set
//   Merge: set union — trivially commutative
//   Use: event logs, append-only collections

// 2P-Set: add + permanent remove
//   Merge: union(add-sets), union(tombstone-sets)
//   Limitation: removed elements cannot be re-added
//   Use: whitelist/blacklist that never reinstates removed items

// OR-Set: add + removable-and-re-addable set
//   Tags per element; tombstone specific tags
//   Merge: union tags, union tombstones
//   Use: shopping cart, collaborative document elements, Riak set type

// LWW-Register: last-write-wins scalar value
//   Merge: keep value with highest timestamp
//   Use: user profile fields, configuration values
//   Risk: clock skew can cause newer writes to be discarded

// MV-Register (Multi-Value Register): keep all concurrent values
//   Merge: union all undominated values (like Git merge conflicts)
//   Use: when application must see and resolve concurrent values

// KEY PROPERTY for state-based CRDTs:
//   merge must be: commutative + associative + idempotent
//   This forms a 'join-semilattice' — merge always moves state 'upward'
